  'demo.tour.ui.missing': 'Ekranın o kısmı şu an görünmüyor. İleri ile devam edin — bu arada ürün tamamen sizin.',
  'demo.tour.ui.endTitle': 'Gördüğünüz gerçek üründü',
  'demo.tour.ui.endBody': 'Az önce gördüğünüz her şey tarayıcınızda, uydurma verilerle çalışıyor. Kendi başınıza gezmeye devam edin ya da ekibiniz için bir çalışma alanı açın.',
