  'trialMail.approved.subject': '{company} için Curahold deneme hesabınız hazır',
  "trialMail.approved.body": "Merhaba {name},\n\nGüzel haber: {company} için Curahold deneme hesabınız hazır. {seats} kişilik yer var ve {until} tarihine kadar açık.\n\nŞirketinizi kurmak için bu bağlantıyla giriş yapın. Bağlantı bir kez ve 7 gün boyunca çalışır:\n\n{link}\n\nİçeride kurulum planınız, ekibinizi davet etmek ve araçlarınızı bağlamak için adım adım yol gösterir. Bir sorun olursa bu e-postayı yanıtlamanız yeterli.\n\nCurahold ekibi",
  'trialMail.rejected.subject': '{company} için Curahold deneme talebiniz hakkında',
  "trialMail.rejected.body": "Merhaba {name},\n\nCurahold'a gösterdiğiniz ilgi ve {company} hakkında bize vakit ayırıp bilgi verdiğiniz için teşekkür ederiz.\n\nBu talep için şu an deneme hesabı açamıyoruz. Bu, ekibinizle ilgili bir değerlendirme değil: her şirkete en baştan gerektiği gibi destek olabilmek için denemeleri adım adım açıyoruz.\n\nBilgilerinizi saklıyoruz; size uygun bir deneme sunabildiğimizde sizinle iletişime geçeceğiz. Sizin tarafınızda bir şey değişirse bu e-postayı yanıtlamanız yeterli.\n\nSaygılarımızla,\nCurahold ekibi",
