  'perm.finance.view': "Finans rakamlarını görme",
  "perm.finance.view.hint": "Bağlı muhasebe programından gelen açık bakiye, vadesi geçmiş faturalar ve ödemeler, her müşterinin sayfasında. Bu izin olmadan yalnızca sağlık skorunun içinde bir ödemenin kaç gün geciktiği görünür.",
  'health.signal.payment': "Zamanında ödeme",
  'health.signalHint.payment': "Bağlı muhasebe programından: ödenmemiş en eski faturanın vadesini kaç gün geçtiği. Programla eşleşmeyen müşteriler hesaba katılmaz.",
  'health.why.payment': "{n} vadesi geçmiş fatura, en eskisi {days} gün gecikmiş",
