  'fin.add': "Muhasebe programları",
  "fin.addHint": "Yalnızca okunur: açık bakiye, vadesi geçmiş faturalar ve ödemeler her müşterinin sayfasında görünür, geciken ödemeler sağlık skoruna katılabilir. Programa hiçbir şey yazılmaz.",
  'fin.file.title': "Başka bir program (dosya)",
  'fin.file.start': "Dosya yükle",
  'fin.what.zohobooks': "Zoho Books'tan müşteriler, faturalar ve ödemeler; tüm Zoho veri merkezlerinde.",
  'fin.what.xero': "Xero'dan müşteriler, satış faturaları ve ödemeler.",
  'fin.what.odoo': "Odoo Online, Odoo.sh ya da kendi sunucunuzdaki Odoo'dan müşteriler, faturalar ve ödemeler.",
  'fin.what.freee': "freee Muhasebe'den cari hesaplar (取引先) ve satış işlemleri.",
  'fin.what.parasut': "Paraşüt'ten müşteriler, satış faturaları ve tahsilatlar.",
  'fin.what.quickbooks': "QuickBooks Online'dan müşteriler, faturalar ve ödemeler.",
  'fin.what.finfile': 'Logo, Mikro, Tally, SAP Business One ya da başka bir program: Excel veya CSV dışa aktarımını yükleyin.',
  'fin.steps.zohobooks': 'Zoho Books kuruluşunu görebilen Zoho hesabıyla giriş yapın.\nCurahold\'un kişileri, faturaları ve ödemeleri okumasına izin verin. Yalnızca okuma izni ister.\nBuraya dönünce ilk okumayı başlatın ve eşleşemeyen müşterilere bakın.',
  'fin.steps.xero': 'Xero\'ya giriş yapın ve bağlanacak kuruluşu seçin.\nKişilere ve işlemlere okuma izni verin; Curahold Xero\'da hiçbir şeyi değiştiremez.\nBuraya dönünce ilk okumayı başlatın ve eşleşemeyen müşterilere bakın.',
  'fin.steps.freee': 'freee\'ye giriş yapın ve bağlanacak şirketi (事業所) seçin.\nErişime izin verin; Curahold yalnızca cari hesapları ve satış işlemlerini okur.\nBuraya dönünce ilk okumayı başlatın ve eşleşemeyen müşterilere bakın.',
  'fin.steps.quickbooks': 'Intuit\'e giriş yapın ve bağlanacak QuickBooks şirketini seçin.\nMuhasebe verilerine erişime izin verin; Curahold yalnızca müşterileri, faturaları ve ödemeleri okur.\nBuraya dönünce ilk okumayı başlatın ve eşleşemeyen müşterilere bakın.',
  'fin.steps.odoo': 'Odoo\'da profilinizi açın → Tercihler → Hesap Güvenliği ve bir API anahtarı oluşturun.\nOdoo adresini ve kullanıcı adını not alın. Odoo.sh\'ta ya da kendi sunucunuzda veritabanı adını da.\nAşağıya girin. Odoo Online\'da API erişimi Custom planını gerektirir (Odoo\'nun kuralı).',
  'fin.steps.parasut': 'Şirketiniz için Paraşüt destekten API erişimi isteyin; size bir client ID ve client secret gönderirler.\nŞirket numaranız adres çubuğunda uygulama.parasut.com/ adresinden sonraki sayıdır.\nBunları bir Paraşüt kullanıcısının e-postası ve şifresiyle girin. Şifre bir anahtar almak için bir kez kullanılır ve saklanmaz.',
  'fin.steps.finfile': 'Müşterileri, faturaları ve ödemeleri programınızdan Excel ya da CSV olarak dışa aktarın.\nBunları şablonun sütunlarına yerleştirin; şablonu sonraki ekranda indirebilirsiniz.\nÖnce müşterileri, sonra faturaları, sonra ödemeleri yükleyin. Daha güncel rakamlar istediğinizde yeni bir dosya yükleyin.',
  'support.field.odoo.url': "Odoo adresi",
