  'demo.tour.sprint.4.title': "Önümüzdeki haftalar, kişi kişi",
  'demo.tour.sprint.4.body': "Bitiş haftasına göre açık görevler, kaçının müşteriye söz olduğu ve puanları: daha fazlasını planlamadan önce kimin yeri var.",
  'demo.tour.handover.title': "Kazanılan fırsattan müşteri ekibine",
  'demo.tour.handover.blurb': "Satış fırsatı kapatır; müşteriye bakacak ekip aynı sayfada devralır, yolda hiçbir şey kaybolmaz.",
  'demo.tour.handover.1.title': "Aşamaya göre fırsatlar",
  'demo.tour.handover.1.body': 'Her sütun bir aşama. Fırsat kapanınca Kazanıldı’ya sürükleyin.',
  'demo.tour.handover.2.title': "Fırsat hikayesini taşır",
  'demo.tour.handover.2.body': "Kimlerin dahil olduğu, neyin söz verildiği ve ne zaman yenileneceği fırsatla birlikte kalır; sıradaki kişi için.",
  'demo.tour.handover.3.title': "Müşteri ekibinin görünümü",
  'demo.tour.handover.3.body': "Fırsat kazanıldığı anda müşteri burada: sahibi, sağlığı ve sıradaki söz tek kartta.",
  'demo.tour.handover-loop.title': "Kazanılan fırsattan “sizin için yaptık”a",
  'demo.tour.handover-loop.blurb': "Satış kazanınca devir kartı, ürün işine bağlanan talepler ve iş yayına girince müşteriye dönen mesaj.",
  'demo.tour.handover-loop.1.title': "Satış bunu az önce kazandı",
  "demo.tour.handover-loop.1.body": 'Cedarmoor Health, Satış hunisinde iki yıllık yenilemeyi imzaladı. Müşteriyi açın.',
  'demo.tour.handover-loop.2.title': "Tek kart, hiçbir şey kaybolmaz",
  'demo.tour.handover-loop.2.body': "Kişiler ve bize bakışları, Satış’ın verdiği sözler, Ürün’den hâlâ bekledikleri, tarihler ve satış yazışmasının sonu. Kimsenin oturup yazması gerekmedi.",
  'demo.tour.handover-loop.3.title': 'Onaylayın, sahibi olsun',
  'demo.tour.handover-loop.3.body': 'Müşteri Başarısı’nda (şirketinizde varsa Onboarding’de) kimin devralacağını ve başlayacak planı seçin. Kartın her yerinden Ctrl+Enter ile de olur.',
  'demo.tour.handover-loop.4.title': "Bir şey istemiş bir müşteri",
  'demo.tour.handover-loop.4.body': 'Quillfield Retail, Ürün’den iki şey istedi. Açın.',
  'demo.tour.handover-loop.5.title': "Bekledikleri",
  'demo.tour.handover-loop.5.body': "Sözler ve istedikleri ürün işi: durum, sprint bitişi ve departman; müşteriyi görebilen herkes görür, Ürün’ün panosunu açmadan.",
  'demo.tour.handover-loop.6.title': 'Yayında: haber verin',
  'demo.tour.handover-loop.6.body': 'İş bitince sahibine bir görev ve bu taslak mesaj düştü. E-postanıza kopyalayın ya da portal talebini kapatın. Hiçbir şey kendiliğinden gönderilmez.',
  'demo.tour.handover-loop.7.title': "Sıradaki talebi bağla",
  'demo.tour.handover-loop.7.body': 'Ürün işlerinde arayın ve talebi iki tuşla bağlayın. Ürün’ün backlog’u kaç müşterinin beklediğini, değerlerini ve en yakın kimin yenileyeceğini gösterir.',
  'demo.tour.move-in.title': 'Kendi dosyanızı getirin',
  'demo.tour.move-in.blurb': 'Şu an kullandığınız araçtan bir dışa aktarımı bırakın, kendi işlerinizi Curahold’da görün. Demoda dosya cihazınızdan hiç çıkmaz.',
  'demo.tour.move-in.1.title': "Her dışa aktarım, tek yer",
  'demo.tour.move-in.1.body': 'Buraya bir CSV, Excel tablosu ya da bir panonun JSON dışa aktarımını bırakın. Curahold müşteriyle görevi sütun adlarından ayırt eder.',
  'demo.tour.move-in.2.title': 'Dosyanız sizde kalır',
  'demo.tour.move-in.2.body': "Demonun tamamı bu tarayıcı sekmesinde çalışır. Hiçbir şey yüklenmez; sayfayı yenileyince unutulur.",
  'demo.tour.move-in.3.title': 'Kaydetmeden önce kontrol edin',
  'demo.tour.move-in.3.body': 'Alt görevler, yorumlar, kendi alanlarınız ve “şunu bekliyor” bağları da gelir. Kuru prova neyin gelip neyin gelmeyeceğini söyler; kırk liste birkaç departman panosunda birleşir.',
  'demo.tour.team-load.title': "Kimin yeri var, hangi müşteri bekliyor",
  'demo.tour.team-load.blurb': "Önümüzdeki haftalar kişi kişi ve her müşterinin açık işleri, talepleri ve destek talepleri tek sayfada.",
  'demo.tour.team-load.1.title': "Önümüzdeki haftalar",
  'demo.tour.team-load.1.body': "Her hücre bir kişinin haftası: o hafta bitmesi gereken açık görevler, müşteriye söz verilenler ve puanlar. Renk, her zamankinden yoğun mu hafif mi olduğunu söyler.",
  'demo.tour.team-load.2.title': "Tüm müşteriler bir arada",
  'demo.tour.team-load.2.body': 'Açık ve geciken işler, portaldan gelen talepler ve henüz çözülmemiş destek talepleri; en yoğunu başta. Sayfasını açmak için bir müşteriye tıklayın.',
