  "hooks.how.esign": "DocuSign'da: Settings → Connect → Add Configuration → Custom. Adresi “URL to publish” olarak yapıştırın, JSON seçin, Envelope Sent, Completed, Declined ve Voided'ı işaretleyin, burada yazdığınız anahtarla HMAC'i açın.",
